// // // // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // // // // Function to insert a node at the front of the list
// // // // // // // // // // // // // // // // // // // // void insertFront(DoublyLinkedList *dll, int value)
// // // // // // // // // // // // // // // // // // // // {
