#include <stdio.h>
#include <string.h>

int main() {
    int k, n;
    scanf("%d %d", &k, &n);
    char a[k][100]; // Assuming a maximum string length of 100 characters
    char b[n][100];
    char *s;
    int c[n];
    for (int i = 0; i < n; i++)
        c[i] = 0;
    for (int i = 0; i < k; i++) {
        scanf("%s", a[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%s", b[i]);
    }
    
    for (int i = 0; i < k; i++) {
        for (int j = 0; j < n; j++) {
            s = strstr(a[i], b[j]);
            if (s) c[j] = 1;
        }
    }
    
    for (int i = 0; i < n; i++) {
        if (c[i] == 1) {
            printf("Good\n");
        } else {
            printf("Bad\n");
        }
    }
    
    return 0;
}
